const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const walvisBay = ee.Geometry.Point([14.5053, -22.9576]); // Walvis Bay, Namibia
  const region = walvisBay.buffer(5000); // 5km buffer around the point

  // 2. Data Acquisition
  const modisCol = ee.ImageCollection('MODIS/061/MOD13Q1');

  // February 2021 data
  const feb2021 = modisCol
    .filterBounds(region)
    .filterDate('2021-02-01', '2021-03-01')
    .select('NDVI');

  // February 2010-2020 baseline data
  const baselineCol = modisCol
    .filterBounds(region)
    .filter(ee.Filter.calendarRange(2, 2, 'month')) // February only
    .filter(ee.Filter.calendarRange(2010, 2020, 'year'))
    .select('NDVI');

  // Check collection sizes
  const feb2021Size = feb2021.size().getInfo();
  const baselineSize = baselineCol.size().getInfo();

  console.log(`2021 February Images: ${feb2021Size}`);
  console.log(`2010-2020 February Images: ${baselineSize}`);

  if (feb2021Size === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI for baseline
  const baselineMean = baselineCol.mean().multiply(0.0001); // Scale factor for MODIS NDVI
  const feb2021Mean = feb2021.mean().multiply(0.0001);

  // 4. Calculate pixel counts to check for valid data
  const baselineCount = baselineMean
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

  const feb2021Count = feb2021Mean
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`2021 valid pixels: ${feb2021Count}`);

  if (baselineCount === 0 || feb2021Count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Extract NDVI values
  const baselineNDVI = baselineMean
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

  const feb2021NDVI = feb2021Mean
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

  console.log(`Baseline NDVI (2010-2020 Feb avg): ${baselineNDVI?.toFixed(4)}`);
  console.log(`2021 February NDVI: ${feb2021NDVI?.toFixed(4)}`);

  // 6. Validation & Final Answer
  if (baselineNDVI === null || feb2021NDVI === null || 
      isNaN(baselineNDVI) || isNaN(feb2021NDVI)) {
    console.log("<answer>C3</answer>");
  } else if (feb2021NDVI > baselineNDVI) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
